#!/usr/bin/env python3
"""
Einmal ausfuehren im Projekt-Root (da wo package.json liegt):

    python3 apply_i18n_update.py

Macht zwei Dinge:
1. Verschiebt bestehende Routen nach src/app/[locale]/ (nur falls noch
   nicht geschehen -- ueberspringt das sonst).
2. Schreibt/ueberschreibt alle 87 geaenderten/neuen Dateien fuer die
   next-intl-Mehrsprachigkeit (inkl. der redirect()-Fixes fuer next-intl v4
   und next-intl in package.json auf ^4.9.1 gepinnt).

Danach nur noch: npm install && npm run dev
"""
import base64
import os

ROOT = os.getcwd()

MOVE_DIRS = [
    "about", "add-store", "admin", "barrierefreiheit", "claim", "datenschutz",
    "explore", "forgot-password", "impressum", "kategorie", "login", "me",
    "nutzungsbedingungen", "profile", "register", "reset-password", "search",
    "stores", "transfers", "verify-email",
]
MOVE_FILES = ["layout.tsx", "loading.tsx", "error.tsx", "page.tsx"]


def migrate_locale_folder():
    src_app = os.path.join(ROOT, "src", "app")
    locale_dir = os.path.join(src_app, "[locale]")
    os.makedirs(locale_dir, exist_ok=True)

    moved_any = False
    for d in MOVE_DIRS:
        src = os.path.join(src_app, d)
        dst = os.path.join(locale_dir, d)
        if os.path.isdir(src) and not os.path.exists(dst):
            os.rename(src, dst)
            moved_any = True
            print(f"  verschoben: src/app/{d} -> src/app/[locale]/{d}")

    for f in MOVE_FILES:
        src = os.path.join(src_app, f)
        dst = os.path.join(locale_dir, f)
        if os.path.isfile(src) and not os.path.exists(dst):
            os.rename(src, dst)
            moved_any = True
            print(f"  verschoben: src/app/{f} -> src/app/[locale]/{f}")

    if not moved_any:
        print("  (nichts zu verschieben -- offenbar schon migriert)")


