def write_files():
    for rel, b64content in FILES.items():
        path = os.path.join(ROOT, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as f:
            f.write(base64.b64decode(b64content))
        print(f"  geschrieben: {rel}")


if __name__ == "__main__":
    print("1) Migriere Ordnerstruktur nach src/app/[locale]/ ...")
    migrate_locale_folder()
    print()
    print(f"2) Schreibe {len(FILES)} Dateien ...")
    write_files()
    print()
    print("Fertig. Jetzt: npm install && npm run dev")